(function(root){'use strict';
const A=root.CustomerAllocations||(typeof require==='function'?require('./customer-allocations-model.js'):null);
const day=v=>typeof v==='string'&&/^20[0-9]{2}-[0-9]{2}-[0-9]{2}$|^2100-[0-9]{2}-[0-9]{2}$/.test(v)&&Number.isFinite(Date.parse(v+'T00:00:00Z'))&&new Date(v+'T00:00:00Z').toISOString().slice(0,10)===v;
function schedule(rows){if(!Array.isArray(rows)||rows.length<1||rows.length>60)throw Error('لە ١ تا ٦٠ قیست دابنێ.');let last='',total=0n;const items=rows.map(r=>{if(!r||!day(r.due_date)||r.due_date<=last)throw Error('بەروارەکان بە ڕیز و جیاواز بنووسە.');last=r.due_date;const n=A.money(r.amount,100000000000000n);if(n<1n)throw Error('بڕی هەر قیستێک دەبێت زیاتر لە سفر بێت.');total+=n;return {due_date:r.due_date,amount:n.toString()};});if(total>100000000000000n)throw Error('کۆی قیستەکان لە سنوور زیاترە.');return {items,total};}
function validate(data,customer,owner){const fail=()=>{throw Error('خشتەی قیستەکان تەواو نییە یان حسابەکان یەک ناگرنەوە.');};
 if(!owner||data?.owner_id!==owner||data.customer_id!==customer||data.currency!=='IQD'||data.timezone!=='Asia/Baghdad'||!Number.isFinite(Date.parse(data.generated_at))||!day(data.today)||!Array.isArray(data.plans)||data.plans.length>500)fail();
 const today=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Baghdad',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date(data.generated_at));const part=k=>today.find(x=>x.type===k).value;if(data.today!==part('year')+'-'+part('month')+'-'+part('day'))fail();
 const ledger=customer?A.validate(data.ledger,customer,owner):null;if(!customer&&data.ledger!==null)fail();
 const ids=new Set(),cancelIds=new Set(),active=new Set(),customers=new Map();let overdue=0n,due=0n,remaining=0n,uncertain=0;
 const plans=data.plans.map(p=>{if(!A.uuid(p?.id)||ids.has(p.id)||!A.uuid(p.customer_id)||customer&&p.customer_id!==customer||!A.uuid(p.charge_entry_id)||typeof p.customer_name!=='string'||!p.customer_name.trim()||typeof p.note!=='string'||!p.note.trim()||!Number.isFinite(Date.parse(p.created_at))||A.money(p.charge_no)<1n)fail();ids.add(p.id);
  const s=schedule(p.schedule),amount=A.money(p.amount,100000000000000n),allocated=A.money(p.allocated,100000000000000n),unassigned=A.money(p.unassigned);if(amount!==s.total||allocated>amount)fail();
  const cancelled=p.cancellation_id!==null;if(cancelled){if(!A.uuid(p.cancellation_id)||cancelIds.has(p.cancellation_id)||typeof p.cancel_reason!=='string'||!p.cancel_reason.trim()||!Number.isFinite(Date.parse(p.cancelled_at)))fail();cancelIds.add(p.cancellation_id);}else if(p.cancel_reason!==null||p.cancelled_at!==null||active.has(p.charge_entry_id))fail();else active.add(p.charge_entry_id);
  if(customers.has(p.customer_id)&&customers.get(p.customer_id)!==p.unassigned)fail();customers.set(p.customer_id,p.unassigned);
  if(ledger){const charge=ledger.entries.get(p.charge_entry_id);if(charge?.kind!=='charge'||charge.movement_no!==p.charge_no||charge.allocated!==p.allocated||ledger.unallocated!==unassigned||p.customer_name!==ledger.data.customer.name)fail();if(!cancelled&&A.money(charge.amount)-A.money(charge.reversed)!==amount)fail();}
  let paid=allocated;const rows=s.items.map((r,i)=>{const n=A.money(r.amount),covered=paid<n?paid:n;paid-=covered;const left=n-covered;const state=cancelled?'cancelled':left===0n?'paid':unassigned>0n?'unclassified':r.due_date<data.today?'overdue':r.due_date===data.today?'today':'upcoming';if(!cancelled){remaining+=left;if(state==='overdue')overdue+=left;if(state==='today')due+=left;}return {...r,index:i+1,paid:covered.toString(),remaining:left.toString(),state};});if(!cancelled&&unassigned>0n)uncertain++;return {...p,rows,cancelled};
 });return {data,ledger,plans,active,overdue,due,remaining,uncertain};
}
const labels={paid:'پارەدراوە',overdue:'دواکەوتوو',today:'ئەمڕۆ',upcoming:'داهاتوو',unclassified:'پێویستی بە دابەشکردنی پارەدانە',cancelled:'هەڵوەشاوە'};
function selected(snapshot,mode){return snapshot.plans.flatMap(p=>p.rows.map(r=>({plan:p,row:r}))).filter(x=>mode==='history'||!x.plan.cancelled&&(mode!=='alerts'||['overdue','today','unclassified'].includes(x.row.state)));}
function csv(snapshot,mode){const text=v=>{let s=String(v);if(/^[\s]*[=+\-@]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';};const rows=[['بەرواری ڕاپۆرت','کڕیار','ناسنامەی کڕیار','تۆماری قەرز','ناسنامەی خشتە','قیست','بەروار','بڕ','پارەدراوی بەستراو','نەبەستراوی قیست','دۆخ','پارەدانی دابەشنەکراوی کڕیار','تێبینی','هۆکاری هەڵوەشاندنەوە']];for(const {plan:p,row:r} of selected(snapshot,mode))rows.push([snapshot.data.generated_at,p.customer_name,p.customer_id,'D-'+p.charge_no,p.id,r.index,r.due_date,r.amount,r.paid,r.remaining,labels[r.state],p.unassigned,p.note,p.cancel_reason||'']);return '\ufeff'+rows.map(r=>r.map(text).join(',')).join('\r\n')+'\r\n';}
root.Installments={day,schedule,validate,labels,selected,csv};if(typeof module==='object'&&module.exports)module.exports=root.Installments;
})(globalThis);
